def compute(vars):
    allowance = vars["v1"]
    receivables = vars["v2"]
    if receivables == 0:
        return None
    doubtful_percentage = abs(allowance) / receivables * 100
    return {
        "value": doubtful_percentage,
        "trace": {
            "allowance": allowance,
            "trade_and_other_accounts_receivable": receivables,
            "doubtful_percentage": doubtful_percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
